import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused clamp_min + division kernel
fused_clamp_div_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_clamp_div_kernel(const float* input, float* output, int num_elements, float min_value, float divisor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        val = fmaxf(val, min_value);
        output[idx] = val / divisor;
    }
}

torch::Tensor fused_clamp_div_cuda(torch::Tensor input, float min_value, float divisor) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_clamp_div_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        min_value,
        divisor
    );

    return output;
}
"""

fused_clamp_div_cpp = "torch::Tensor fused_clamp_div_cuda(torch::Tensor input, float min_value, float divisor);"

# Load custom CUDA op
fused_clamp_div = load_inline(
    name="fused_clamp_div",
    cpp_sources=fused_clamp_div_cpp,
    cuda_sources=fused_clamp_div_source,
    functions=["fused_clamp_div_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, min_value, divisor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.min_value = min_value
        self.divisor = divisor
        self.fused_clamp_div = fused_clamp_div

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_clamp_div.fused_clamp_div_cuda(x, self.min_value, self.divisor)
        return x
